import React, { useMemo } from 'react';
import Button from '@mui/material/Button';
import Dialog from '@mui/material/Dialog';
import DialogActions from '@mui/material/DialogActions';
import DialogContent from '@mui/material/DialogContent';
import DialogTitle from '@mui/material/DialogTitle';
import {
  Box,
  CircularProgress,
  Grid,
  Stack,
  TextField,
  Typography,
  useMediaQuery,
} from '@mui/material';
import LocalShippingOutlinedIcon from '@mui/icons-material/LocalShippingOutlined';
import FieldHeader from '../../../components/FieldHeader';
import { theme } from '../../../theme';
import { useFormik } from 'formik';
import { useNotifier } from '../../../core/Notifier';
import { appColors, HEADER_GRADIENT } from '../../../theme/appColors';
import { useTranslation } from 'react-i18next';
import { uploadImage } from '../../../core/utils';
import { useNewSupplierMutation } from '../../posApi';
import { ISupplierDetailsData } from '../../../core/Interface/supplier.interface';

interface ISupplierManage {
  title: string;
  openModel?: boolean;
  handleCloseDialog: (close: boolean) => void;
  data?: ISupplierDetailsData;
  isImageEnabled: boolean;
}

const SupplierManage = ({
  title,
  openModel = false,
  handleCloseDialog,
  data,
  isImageEnabled,
}: ISupplierManage) => {
  const [open] = React.useState(openModel);
  const isMobile = useMediaQuery(theme.breakpoints.down('md'));
  const [newSupplier, { isLoading }] = useNewSupplierMutation();
  const { showErrorMessage, showMessage } = useNotifier();
  const { t } = useTranslation(['common', 'suppliermanage']);
  const buttonText = data ? t('common:update') : t('common:create');

  const handleClose = () => {
    handleCloseDialog(false);
  };

  const [selectedImage, setSelectedImage] = React.useState<File | undefined>(
    undefined
  );
  const [isImageUploading, setIsImageUploading] = React.useState(false);

  const validateMobileNumber = (value: string) => {
    const mobileRegex = /^[0-9]+$/; // Only allow numbers
    const isMobileValid =
      (value.startsWith('0') && value.length === 10) ||
      (!value.startsWith('0') && value.length === 9);
    return isMobileValid && mobileRegex.test(value);
  };
  const validateName = (value: string) => {
    return /\S/.test(value);
  };

  const validateEmail = (value: string) => {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return emailRegex.test(value);
  };

  const formik = useFormik({
    initialValues: {
      id: data?.id,
      suppliername: data?.supplierName,
      contactperson: data?.contactPerson,
      mobile: data?.mobile,
      email: data?.email,
      imageUrl: data?.imageUrl,
    },
    onSubmit: async (values) => {
      try {
        const formData = new FormData();
        let imageUrl: string | undefined = data?.imageUrl;

        if (selectedImage) {
          setIsImageUploading(true);
          formData.append('imageUrl', selectedImage);
          imageUrl = (await uploadImage(selectedImage)) || '';
          setIsImageUploading(false);
        }
        if (!validateMobileNumber(values.mobile || '')) {
          showErrorMessage('Mobile number should be valid.');
          return;
        }

        if (!validateName(values.suppliername || '')) {
          showErrorMessage('name cannot be empty or contain only spaces. ');
          return;
        }

        if (!validateEmail(values.email || '')) {
          showErrorMessage('Please enter a valid email address.');
          return;
        }

        values.imageUrl = imageUrl;
        const tempData = {
          id: values?.id,
          suppliername: values.suppliername,
          contactperson: values.contactperson,
          mobile: values?.mobile || '',
          email: values?.email,
          imageUrl,
        };

        if (!data) {
          delete values.id;
        }
        const addSupplierResponse = await newSupplier(tempData).unwrap();
        if (!addSupplierResponse.status) {
          showErrorMessage(addSupplierResponse.message);
        } else {
          showMessage(addSupplierResponse.message);
          handleClose();
        }
      } catch (error) {
        showErrorMessage((error as Error).message);
      }
    },
  });

  const formValid = useMemo(() => {
    return (
      formik.values.suppliername &&
      formik.values.contactperson &&
      formik.values.mobile &&
      validateName(formik.values.suppliername) &&
      validateMobileNumber(formik.values.mobile) &&
      validateEmail(formik.values.email || '')
    );
  }, [formik]);

  const handleImageChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = event.target.files;

    if (files && files.length > 0) {
      const file = files[0];
      setSelectedImage(file);
    } else {
      setSelectedImage(undefined);
    }
  };

  return (
    <div>
      <form noValidate onSubmit={formik.handleSubmit}>
        <Dialog
          aria-describedby="alert-dialog-description"
          fullScreen={isMobile}
          fullWidth
          maxWidth="sm"
          open={open}
          PaperProps={{ sx: { borderRadius: isMobile ? 0 : '12px', overflow: 'hidden' } }}
        >
          <DialogTitle sx={{ p: 0 }}>
            <Box sx={{ background: HEADER_GRADIENT, px: 3, py: 2 }}>
              <Stack alignItems="center" direction="row" spacing={1.5}>
                <Box sx={{ alignItems: 'center', background: 'rgba(255,255,255,0.15)', borderRadius: '8px', display: 'flex', height: 36, justifyContent: 'center', width: 36, flexShrink: 0 }}>
                  <LocalShippingOutlinedIcon sx={{ color: '#fff', fontSize: 20 }} />
                </Box>
                <Box>
                  <Typography sx={{ color: '#fff', fontSize: '1rem', fontWeight: 800, lineHeight: 1.2 }}>{title}</Typography>
                  <Typography sx={{ color: 'rgba(255,255,255,0.7)', fontSize: '0.72rem', fontWeight: 500 }}>Create or edit supplier</Typography>
                </Box>
              </Stack>
            </Box>
          </DialogTitle>
          <DialogContent sx={{ px: 3, pt: 3, pb: 1 }}>
            <Box>
              <Grid container>
                <GridItem>
                  <FieldHeader title={t('suppliermanage:title.suppliername')} />
                  <TextField
                    autoComplete="off"
                    placeholder={t('suppliermanage:title.suppliername')}
                    size="small"
                    {...formik.getFieldProps('suppliername')}
                    error={
                      formik.touched.suppliername &&
                      !validateName(formik.values.suppliername || '')
                    }
                    helperText={
                      formik.touched.suppliername &&
                      !validateName(formik.values.suppliername || '') && (
                        <span style={{ textTransform: 'none' }}>
                          name cannot be empty or contain only spaces.
                        </span>
                      )
                    }
                    sx={{ height: `${theme.spacing(5)}`, width: '100%' }}
                  />
                </GridItem>
                <GridItem sx={{ pt: 2 }}>
                  <FieldHeader
                    title={t('suppliermanage:title.contactPerson')}
                  />
                  <TextField
                    autoComplete="off"
                    placeholder={t('suppliermanage:title.contactPerson')}
                    size="small"
                    {...formik.getFieldProps('contactperson')}
                    sx={{ height: `${theme.spacing(5)}`, width: '100%' }}
                  />
                </GridItem>
                <GridItem sx={{ pt: 2 }}>
                  <FieldHeader title={t('suppliermanage:title.email')} />
                  <TextField
                    autoComplete="off"
                    placeholder={t('suppliermanage:title.email')}
                    size="small"
                    {...formik.getFieldProps('email')}
                    error={
                      formik.touched.email &&
                      (!validateEmail(formik.values.email || '') ||
                        formik.values.email?.length === 0)
                    }
                    helperText={
                      formik.touched.email &&
                      (!validateEmail(formik.values.email || '') ||
                        formik.values.email?.length === 0) && (
                        <span style={{ textTransform: 'none' }}>
                          Please enter valid email.
                        </span>
                      )
                    }
                    sx={{ height: `${theme.spacing(5)}`, width: '100%' }}
                  />
                </GridItem>
                <GridItem sx={{ pt: 2 }}>
                  <FieldHeader title={t('suppliermanage:title.mobile')} />
                  <TextField
                    autoComplete="off"
                    placeholder={t('suppliermanage:title.mobile')}
                    size="small"
                    {...formik.getFieldProps('mobile')}
                    error={
                      formik.touched.mobile &&
                      (!validateMobileNumber(formik.values.mobile || '') ||
                        formik.values.mobile?.length === 0)
                    }
                    helperText={
                      formik.touched.mobile &&
                      (!validateMobileNumber(formik.values.mobile || '') ||
                        formik.values.mobile?.length === 0) && (
                        <span style={{ textTransform: 'none' }}>
                          Please enter valid mobile number.
                        </span>
                      )
                    }
                    inputProps={{
                      maxLength: 10,
                      type: 'tel',
                    }}
                    sx={{ height: `${theme.spacing(5)}`, width: '100%' }}
                  />
                </GridItem>
                {isImageEnabled && (
                <GridItem sx={{ pt: 2 }}>
                  <FieldHeader title={t('suppliermanage:title.upload image')} />
                  <Box
                    sx={{
                      border: '2px dashed #cccccc',
                      borderRadius: '8px',
                      padding: '16px',
                      display: 'flex',
                      flexDirection: 'column',
                      alignItems: 'center',
                      justifyContent: 'center',
                      height: '200px',
                    }}
                  >
                    <Grid
                      container
                      spacing={2}
                    >
                      <Grid
                        item
                        xs={8}
                      >
                        {selectedImage && (
                          <img
                            alt="Selected"
                            height="160px"
                            src={URL.createObjectURL(selectedImage)}
                            style={{ position: 'inherit' }}
                            width="80%"
                          />
                        )}
                        {!selectedImage && data && (
                          <img
                            alt="Selected"
                            height="160px"
                            src={data.imageUrl}
                            style={{ position: 'inherit' }}
                            width="80%"
                          />
                        )}
                      </Grid>
                      <Grid
                        item
                        xs={4}
                      >
                        <TextField
                          InputProps={{
                            inputProps: { accept: '.jpg, .jpeg, .png' },
                          }}
                          onChange={handleImageChange}
                          type="file"
                        />
                        {isImageUploading && (
                          <Box sx={{ pr: 2, pt: 0.5 }}>
                            <CircularProgress
                              size={16}
                              sx={{ color: 'white' }}
                            />
                          </Box>
                        )}
                      </Grid>
                    </Grid>
                  </Box>
                </GridItem>
                )}
              </Grid>
            </Box>
          </DialogContent>
          <DialogActions sx={{ borderTop: '1px solid #E2E8F0', gap: 1.5, px: 3, py: 2 }}>
            <Button
              onClick={handleClose}
              sx={{
                borderColor: '#CBD5E1',
                borderRadius: '8px',
                color: '#475569',
                fontWeight: 600,
                height: 40,
                minWidth: 110,
                px: 3,
                textTransform: 'none',
                '&:hover': { background: '#F1F5F9', borderColor: '#94A3B8' },
              }}
              variant="outlined"
            >
              {t('common:cancel')}
            </Button>
            <Button
              autoFocus
              disabled={!formValid || isLoading || isImageUploading}
              onClick={() => {
                formik.handleSubmit();
              }}
              sx={{
                background: HEADER_GRADIENT,
                borderRadius: '8px',
                boxShadow: '0 4px 14px rgba(15,29,77,0.25)',
                color: '#fff',
                fontWeight: 700,
                height: 40,
                minWidth: 110,
                px: 3,
                textTransform: 'none',
                '&:hover': { opacity: 0.9 },
                '&.Mui-disabled': { background: '#CBD5E1', color: '#94A3B8', boxShadow: 'none' },
              }}
              type="submit"
              variant="contained"
            >
              {(isLoading || isImageUploading) && (
                <Box sx={{ pr: 2, pt: 0.5 }}>
                  <CircularProgress
                    size={16}
                    sx={{ color: 'white' }}
                  />
                </Box>
              )}
              {buttonText}
            </Button>
          </DialogActions>
        </Dialog>
      </form>
    </div>
  );
};

export default React.memo(SupplierManage);

// eslint-disable-next-line react/no-multi-comp
const GridItem = ({ ...rest }) => {
  return (
    <Grid
      item
      key={1}
      lg={12}
      sm={12}
      xs={12}
      {...rest}
    />
  );
};
