import { Box, Grid, Paper, Stack, styled, Typography } from '@mui/material';
import React, { useState } from 'react';
import AddIcon from '@mui/icons-material/Add';
import LocalShippingOutlinedIcon from '@mui/icons-material/LocalShippingOutlined';
import NewSupplier from '../../../SupplierManagement/components/NewSupplier';

const Item = styled(Paper)(({ theme }) => ({
  ...theme.typography.body2,
  textAlign: 'center',
  verticalAlign: 'middle',
  height: 'var(--tile-h)',
  display: 'flex',
  justifyContent: 'center',
  alignItems: 'center',
  borderRadius: '10px',
  cursor: 'pointer',
}));

const fillerCount = 7;

const PurchaseFourthSection = () => {
  const [openCreateSupplier, setOpenCreateSupplier] = useState(false);

  const handleCloseCreateSupplier = () => {
    setOpenCreateSupplier(false);
    window.requestAnimationFrame(() => {
      document.getElementById('purchase-supplier-search')?.focus();
    });
  };

  return (
    <Box>
      <Grid container spacing={1}>
        {/* Add Supplier */}
        <Grid item key="fourth_supplier" md={1.5} sm={4} xs={4}>
          <Item
            onClick={() => setOpenCreateSupplier(true)}
            sx={{ background: 'linear-gradient(135deg, #f3e8ff 0%, #e9d5ff 100%)', position: 'relative' }}
          >
            <AddIcon
              sx={{ fontSize: 16, color: '#7c3aed', position: 'absolute', top: 7, right: 7, opacity: 0.9 }}
            />
            <Stack alignItems="center" direction="column">
              <LocalShippingOutlinedIcon sx={{ fontSize: 28, color: '#7c3aed' }} />
              <Typography sx={{ fontWeight: 700, fontSize: 11, color: '#0F1D4D', mt: '2px' }}>
                Supplier
              </Typography>
            </Stack>
          </Item>
        </Grid>

        {/* Filler tiles */}
        {Array.from(Array(fillerCount).keys()).map((k) => (
          <Grid item key={'fourth_filler_' + k} md={1.5} sm={4} xs={4}>
            <Item sx={{ background: 'rgba(148,163,184,0.15)', cursor: 'default' }} />
          </Grid>
        ))}
      </Grid>

      {openCreateSupplier && (
        <NewSupplier
          handleCloseDialog={handleCloseCreateSupplier}
          isImageEnabled={false}
          openModel={openCreateSupplier}
          title="Add Supplier"
        />
      )}
    </Box>
  );
};

export default React.memo(PurchaseFourthSection);
