import { useSelector } from 'react-redux';
import {
  selectReceiptNo,
  selectBasket,
  selectBasketItems,
  selectDiscount,
  selectSupplierNameOrMobile,
} from './store/BasketSelector';
import { BasketItem } from './store/BasketSlice';
import { useMemo } from 'react';
import {
  IPurchaseItem,
  IPurchaseReqPayload,
} from '../../core/Interface/purchase.interface';
import { useGetAllProductQuery, useGetUserQuery } from '../posApi';
import { IProductData, IProduct } from '../../core/Interface/product.interface';
import { IUserInfo } from '../../core/Interface/user.interface';

const usePurchase = () => {
  const selectItem = useSelector(selectBasketItems);
  const selectBasketStore = useSelector(selectBasket);
  const selectDis = useSelector(selectDiscount);
  const receiptNoFromStore = useSelector(selectReceiptNo);
  const supplierNameOrMobileFromStore = useSelector(selectSupplierNameOrMobile);

  const { data: companyData } = useGetUserQuery();
  const { data: productData, isLoading, isFetching } = useGetAllProductQuery({
    pageIndex: 0,
    pageSize: 5000,
    searchText: '',
  });

  const currencyCode = useMemo(() => {
    if (companyData?.data) {
      const userData = companyData.data as IUserInfo;
      if (userData.company.currencyCode) return userData.company.currencyCode;
    }
    return '';
  }, [companyData]);

  const isImageEnabled = useMemo(() => {
    if (companyData?.data && typeof companyData.data === 'object' && 'company' in companyData.data) {
      return (companyData.data as { company: { isImageEnabled: boolean } }).company.isImageEnabled ?? false;
    }
    return false;
  }, [companyData]);

  const productRecords = useMemo(() => {
    const apiData = productData?.data as IProduct | undefined;
    if (!apiData?.records || isLoading) {
      return [];
    }
    return apiData.records.map((record) => ({ ...record }));
  }, [productData?.data, isLoading]);

  const categoryMemo = useMemo(() => {
    const groupedData: Record<string, IProductData[]> = {};
    if (productRecords.length > 0) {
      productRecords.forEach((re) => {
        const cat = re.categoryName;
        if (!groupedData[cat]) groupedData[cat] = [];
        groupedData[cat].push(re);
      });
    }
    return groupedData;
  }, [productRecords]);

  const calculateSummary: {
    total: number;
    subTotal: number;
    discount: number;
    receiptNo: string;
    supplierNameOrMobile: string;
  } = useMemo(() => {
    const subTotal = selectItem.reduce(getSum, 0);
    const discount = !selectDis.discountAsPercentage
      ? selectDis.discount
      : (subTotal * selectDis.discount) / 100;
    const total = subTotal === 0 ? 0 : subTotal - discount;
    const receiptNo = receiptNoFromStore ?? '';
    const supplierNameOrMobile = supplierNameOrMobileFromStore ?? '';

    return { subTotal, discount, total, receiptNo, supplierNameOrMobile };
  }, [
    selectItem,
    selectDis,
    receiptNoFromStore,
    supplierNameOrMobileFromStore,
  ]);

  const purchaseDetails: IPurchaseReqPayload = {
    subTotal: calculateSummary.subTotal,
    discount: calculateSummary.discount,
    netTotal: calculateSummary.total,
    items: selectItem.map((item) => {
      return {
        productId: item.id,
        productName: item.name,
        qty: item.quanity,
        freeQty: item.freeQty,
        totalQty: item.freeQty + item.quanity,
        unitPrice: item.price,
        isPercentage: item.isDiscountPercentage ?? false,
        discountValue: item.discount,
        discountAmount: item.price - item.cost,
        totalDiscountAmount: (item.price - item.cost) * item.quanity,
        cost: item.cost,
        sellingPrice: item.sellingPrice,
        totalAmount: item.quanity * item.cost,
      } as IPurchaseItem;
    }),
    receiptNo: calculateSummary.receiptNo,
    supplierNameOrMobile: calculateSummary.supplierNameOrMobile,
    totalDiscountAmount: calculateSummary.discount,
    discountValue: selectDis.discount,
    discountAmount: calculateSummary.discount,
    isPercentage: selectDis.discountAsPercentage,
  };

  return {
    calculateSummary,
    selectItem,
    selectBasketStore,
    purchaseDetails,
    categoryMemo,
    productRecords,
    isLoading: isLoading || isFetching,
    currencyCode,
    isImageEnabled,
  };
};

function getSum(total: number, item: BasketItem) {
  return total + item.quanity * item.cost;
}

export default usePurchase;
