/* eslint-disable react/jsx-sort-props */
import * as React from 'react';
import Button from '@mui/material/Button';
import Dialog from '@mui/material/Dialog';
import DialogActions from '@mui/material/DialogActions';
import DialogContent from '@mui/material/DialogContent';
import DialogTitle from '@mui/material/DialogTitle';
import {
  Box,
  Checkbox,
  FormControlLabel,
  Grid,
  Stack,
  TextField,
  Typography,
  useMediaQuery,
} from '@mui/material';
import AddShoppingCartOutlinedIcon from '@mui/icons-material/AddShoppingCartOutlined';
import FieldHeader from '../../../components/FieldHeader';
import { theme } from '../../../theme';
import { useFormik } from 'formik';
import { useMemo } from 'react';
import { useTranslation } from 'react-i18next';
import { useAppDispatch } from '../../../store/hooks';
import { IProductData } from '../../../core/Interface/product.interface';
import { addItem, BasketItem, removeItem } from '../store/BasketSlice';
import { appColors, HEADER_GRADIENT } from '../../../theme/appColors';

interface IAddPurchase {
  openModel?: boolean;
  title: string;
  handleCloseDialog: (close: boolean) => void;
  item?: BasketItem;
  data?: IProductData;
}

const AddPurchase = ({
  title,
  openModel = false,
  handleCloseDialog,
  item,
  data,
}: IAddPurchase) => {
  const { t } = useTranslation(['purchase']);
  const [open] = React.useState(openModel);
  const isMobile = useMediaQuery(theme.breakpoints.down('md'));
  const dispatch = useAppDispatch();
  const sourceId = item?.id ?? data?.id ?? '';
  const sourceName = item?.name ?? data?.name ?? '';
  const sourceCode = item?.code ?? data?.code;
  const sourceSellingPrice = item?.sellingPrice ?? data?.unitPrice ?? null;
  const isEditMode = Boolean(item);

  const handleClose = () => {
    handleCloseDialog(false);
  };

  const handleDelete = () => {
    if (!item) return;
    dispatch(removeItem(item.id));
    handleClose();
  };

  const [sellingPriceChanged, setSellingPriceChanged] = React.useState(false);

  const handleSellingPriceChange = () => {
    setSellingPriceChanged(true);
  };

  const handleSellingPriceBlur = () => {
    setSellingPriceChanged(false);
  };

  const formik = useFormik({
    enableReinitialize: true,
    initialValues: {
      count: item?.quanity,
      sellingPrice: sourceSellingPrice,
      name: sourceName,
      cost: item?.cost ?? null,
      price: item?.price ?? null,
      discount: item?.discount ?? null,
      discountAsPercentage: item?.isDiscountPercentage ?? false,
      total: item?.total ?? null,
      freeQty: item?.freeQty ?? null,
      totalQty: item?.totalQty,
    },
    onSubmit: async (values) => {
      const itemCount: BasketItem = {
        name: values?.name ?? '',
        quanity: values.count ?? 1,
        sellingPrice: values.sellingPrice ?? 0,
        id: sourceId,
        code: sourceCode,
        cost: values?.cost ?? 0,
        price: values?.price ?? 0,
        isDiscountPercentage: values.discountAsPercentage || false,
        total: values?.total ?? 0,
        freeQty:
          values.freeQty !== null && values.freeQty >= 0
            ? values.freeQty
            : 0,
        totalQty: (values.count ?? 0) + (values.freeQty ?? 0),
        discount: values.discount ?? 0,
        discountAmount: (values?.price ?? 0) - (values?.cost ?? 0),
        totalDiscountAmount:
          ((values?.price ?? 0) - (values?.cost ?? 0)) * (values.count ?? 1),
      };
      dispatch(addItem(itemCount));
      handleClose();
    },
  });
  React.useEffect(() => {
    const pricePerUnit = formik.values.price ?? 0;
    const totalUnits = formik.values.count ?? 1;
    const discount = formik.values.discount ?? 0;

    const totalPrice = pricePerUnit * totalUnits;
    const discountAmount = formik.values.discountAsPercentage
      ? (discount / 100) * totalPrice
      : discount * totalUnits;

    const costPerUnit = (totalPrice - discountAmount) / totalUnits;
    formik.setFieldValue('cost', costPerUnit);
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [
    formik.values.price,
    formik.values.count,
    formik.values.discount,
    formik.values.discountAsPercentage,
  ]);

  React.useEffect(() => {
    const totalQuantity =
      (formik.values.count ?? 0) + (formik.values.freeQty ?? 0);
    const totalCost = (formik.values.count ?? 0) * (formik.values.cost ?? 0);
    formik.setFieldValue('total', totalCost);
    formik.setFieldValue('totalQuantity', totalQuantity);
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [formik.values.count, formik.values.cost, formik.values.freeQty]);

  const formValid = useMemo(() => {
    const isCountValid =
      formik.values.count !== undefined && formik.values.count > 0;
    const isSellingPriceValid =
      formik.values.sellingPrice !== undefined &&
      formik.values.sellingPrice &&
      formik.values.sellingPrice > 0;
    const isNameValid =
      formik.values.name !== undefined && formik.values.name.trim() !== '';
    return isCountValid && isSellingPriceValid && isNameValid;
  }, [formik]);

  return (
    <div>
      <form noValidate onSubmit={formik.handleSubmit}>
        <Dialog
          aria-describedby="alert-dialog-description"
          classes={{ paper: 'inherit' }}
          fullScreen={isMobile}
          fullWidth={isMobile}
          maxWidth="lg"
          open={open}
          PaperProps={{ sx: { borderRadius: isMobile ? 0 : '12px', overflow: 'hidden' } }}
        >
          <DialogTitle sx={{ p: 0 }}>
            <Box sx={{ background: HEADER_GRADIENT, px: 3, py: 2 }}>
              <Stack alignItems="center" direction="row" spacing={1.5}>
                <Box sx={{ alignItems: 'center', background: 'rgba(255,255,255,0.15)', borderRadius: '8px', display: 'flex', height: 36, justifyContent: 'center', width: 36, flexShrink: 0 }}>
                  <AddShoppingCartOutlinedIcon sx={{ color: '#fff', fontSize: 20 }} />
                </Box>
                <Box>
                  <Typography sx={{ color: '#fff', fontSize: '1rem', fontWeight: 800, lineHeight: 1.2 }}>{title}</Typography>
                  <Typography sx={{ color: 'rgba(255,255,255,0.7)', fontSize: '0.72rem', fontWeight: 500 }}>
                    {isEditMode ? 'Update purchase item' : 'Add item to purchase'}
                  </Typography>
                </Box>
              </Stack>
            </Box>
          </DialogTitle>
          <DialogContent
            sx={{ width: isMobile ? 'auto' : '40vw', px: 3, pt: 3, pb: 1 }}
          >
            <Box>
              <Grid container>
                <GridItem>
                  <FieldHeader title={t('purchase:name')} />
                  <TextField
                    autoComplete="off"
                    placeholder={t('purchase:name')}
                    size="small"
                    {...formik.getFieldProps('name')}
                    sx={{ height: `${theme.spacing(5)}`, width: '100%' }}
                    disabled
                    InputProps={{
                      style: {
                        background: 'lightgray',
                      },
                    }}
                  />
                </GridItem>
                <GridItem sx={{ pt: 2 }}>
                  <FieldHeader title={t('purchase:quanity')} />
                  <TextField
                    autoComplete="off"
                    placeholder={t('purchase:quanity')}
                    size="small"
                    {...formik.getFieldProps('count')}
                    InputProps={{ inputProps: { min: 1 } }}
                    sx={{ height: `${theme.spacing(5)}`, width: '100%' }}
                    type="number"
                    inputProps={{ step: 'any' }}
                  />
                  <GridItem sx={{ pt: 2 }}>
                    <FieldHeader title={t('purchase:freequanity')} />
                    <TextField
                      autoComplete="off"
                      placeholder={t('purchase:freequanity')}
                      size="small"
                      {...formik.getFieldProps('freeQty')}
                      InputProps={{ inputProps: { min: 0 } }}
                      sx={{ height: `${theme.spacing(5)}`, width: '100%' }}
                      type="number"
                      inputProps={{ step: 'any' }}
                    />
                  </GridItem>
                  <GridItem sx={{ pt: 2 }}>
                    <FieldHeader title={t('purchase:totalQuantity')} />
                    <TextField
                      autoComplete="off"
                      placeholder={t('purchase:totalQuantity')}
                      size="small"
                      value={
                        (formik.values.count ?? 0) +
                        (formik.values.freeQty ?? 0)
                      }
                      InputProps={{ inputProps: { min: 0 } }}
                      sx={{ height: `${theme.spacing(5)}`, width: '100%' }}
                      disabled
                    />
                  </GridItem>
                </GridItem>
                <GridItem sx={{ pt: 2 }}>
                  <FieldHeader title={t('purchase:price')} />
                  <TextField
                    autoComplete="off"
                    placeholder={t('purchase:price')}
                    size="small"
                    {...formik.getFieldProps('price')}
                    InputProps={{ inputProps: { min: 1 } }}
                    sx={{ height: `${theme.spacing(5)}`, width: '100%' }}
                    type="number"
                    inputProps={{ step: 'any' }}
                  />
                </GridItem>
                <GridItem
                  lg={6}
                  sm={6}
                  sx={{ pt: 2 }}
                  xs={6}
                >
                  <FieldHeader title={'Discount'} />
                  <TextField
                    autoComplete="off"
                    placeholder="Discount"
                    size="small"
                    {...formik.getFieldProps('discount')}
                    InputProps={{ inputProps: { min: 0 } }}
                    sx={{ height: `${theme.spacing(5)}`, width: '100%' }}
                    type="number"
                    inputProps={{ step: 'any' }}
                  />
                </GridItem>
                <GridItem
                  lg={6}
                  sm={6}
                  xs={6}
                >
                  <FormControlLabel
                    control={
                      <Checkbox
                        checked={formik.values.discountAsPercentage}
                        {...formik.getFieldProps('discountAsPercentage')}
                      />
                    }
                    label="Is Percentage (%)"
                    sx={{ pt: 5, pl: 2 }}
                  />
                </GridItem>
                <GridItem sx={{ pt: 2 }}>
                  <FieldHeader title={t('purchase:cost')} />
                  <TextField
                    autoComplete="off"
                    placeholder={t('purchase:cost')}
                    size="small"
                    {...formik.getFieldProps('cost')}
                    InputProps={{ inputProps: { min: 0 } }}
                    sx={{ height: `${theme.spacing(5)}`, width: '100%' }}
                    disabled
                  />
                </GridItem>
                <GridItem sx={{ pt: 2 }}>
                  <FieldHeader title={t('purchase:total')} />
                  <TextField
                    autoComplete="off"
                    placeholder={t('purchase:total')}
                    size="small"
                    {...formik.getFieldProps('total')}
                    InputProps={{ inputProps: { min: 0 } }}
                    sx={{ height: `${theme.spacing(5)}`, width: '100%' }}
                    disabled
                  />
                </GridItem>
                <GridItem sx={{ pt: 2 }}>
                  <FieldHeader title={t('purchase:sellingPrice')} />
                  <TextField
                    autoComplete="off"
                    placeholder={t('purchase:sellingPrice')}
                    size="small"
                    {...formik.getFieldProps('sellingPrice')}
                    InputProps={{ inputProps: { min: 1 } }}
                    sx={{ height: `${theme.spacing(5)}`, width: '100%' }}
                    onBlur={handleSellingPriceBlur}
                    onChange={(e) => {
                      handleSellingPriceChange();
                      formik.handleChange(e);
                    }}
                  />
                  {sellingPriceChanged && (
                    <Typography
                      variant="body2"
                      sx={{
                        color: appColors.orange[70],
                      }}
                    >
                      {t('purchase:mesg')}
                    </Typography>
                  )}
                </GridItem>
              </Grid>
            </Box>
          </DialogContent>
          <DialogActions sx={{ borderTop: '1px solid #E2E8F0', gap: 1.5, px: 3, py: 2 }}>
            <Button
              onClick={handleClose}
              sx={{ borderColor: '#CBD5E1', borderRadius: '8px', color: '#475569', fontWeight: 600, height: 40, minWidth: 110, px: 3, textTransform: 'none', '&:hover': { background: '#F1F5F9', borderColor: '#94A3B8' } }}
              variant="outlined"
            >
                {t('purchase:cancel')}
              </Button>
            {isEditMode && (
              <Button
                color="error"
                onClick={handleDelete}
                sx={{ borderRadius: '8px', fontWeight: 600, height: 40, minWidth: 110, px: 3, textTransform: 'none' }}
                variant="outlined"
              >
                Delete
              </Button>
            )}
            <Button
              autoFocus
              disabled={!formValid}
              onClick={() => {
                formik.handleSubmit();

              }}
              sx={{ background: HEADER_GRADIENT, borderRadius: '8px', boxShadow: '0 4px 14px rgba(15,29,77,0.25)', color: '#fff', fontWeight: 700, height: 40, minWidth: 110, px: 3, textTransform: 'none', '&:hover': { opacity: 0.9 }, '&.Mui-disabled': { background: '#CBD5E1', color: '#94A3B8', boxShadow: 'none' } }}
              type="submit"
              variant="contained"
            >
              {isEditMode ? 'Update' : t('purchase:add')}
            </Button>
          </DialogActions>
        </Dialog>
      </form>
    </div>
  );
};

export default React.memo(AddPurchase);

// eslint-disable-next-line react/no-multi-comp
const GridItem = ({ ...rest }) => {
  return (
    <Grid
      item
      key={1}
      lg={12}
      sm={12}
      xs={12}
      {...rest}
    />
  );
};
