import {
  Autocomplete,
  Box,
  Grid,
  InputAdornment,
  TextField,
  Typography,
} from '@mui/material';
import { alpha } from '@mui/material/styles';
import React, { useEffect, useMemo, useRef, useState } from 'react';
import SearchIcon from '@mui/icons-material/Search';
import LocalShippingOutlinedIcon from '@mui/icons-material/LocalShippingOutlined';
import ReceiptLongOutlinedIcon from '@mui/icons-material/ReceiptLongOutlined';
import { useVirtualizer } from '@tanstack/react-virtual';
import { useSelector } from 'react-redux';
import { useTranslation } from 'react-i18next';
import {
  selectSupplierNameOrMobile,
  selectReceiptNo,
} from '../../store/BasketSelector';
import { addMobileReceiptID } from '../../store/BasketSlice';
import { useAppDispatch, useAppSelector } from '../../../../store/hooks';
import { useGetSupplierByMobileQuery } from '../../../posApi';
import usePurchase from '../../usePurchase';
import { IProductData } from '../../../../core/Interface/product.interface';
import { getPriceFormatWithoutCurrency } from '../../../../core/utils';
import AddPurchase from '../AddPurchase';

const TEAL = '#0F8B8D';
const NAVY = '#0F1D4D';
const ITEM_H = 44;
const MAX_VISIBLE = 8;

type SupplierSearchOption = {
  id?: string;
  mobile?: string | null;
  supplierName?: string | null;
  name?: string | null;
  contactPerson?: string | null;
};

const normalizeSupplierValue = (value?: string | null) =>
  value?.trim().toLowerCase() ?? '';

const getSupplierOptionLabel = (supplier: SupplierSearchOption) =>
  supplier.supplierName?.trim() ||
  supplier.name?.trim() ||
  supplier.mobile?.trim() ||
  '';

const getSupplierOptionMobile = (supplier: SupplierSearchOption) =>
  supplier.mobile?.trim() ?? '';

const VirtualListbox = React.forwardRef<
  HTMLDivElement,
  React.HTMLAttributes<HTMLElement>
>(function VirtualListbox({ children, style, ...other }, ref) {
  const items = React.Children.toArray(children);
  const scrollRef = useRef<HTMLDivElement>(null);

  const virtualizer = useVirtualizer({
    count: items.length,
    estimateSize: () => ITEM_H,
    getScrollElement: () => scrollRef.current,
    overscan: 5,
  });

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTop = 0;
  }, [items.length]);

  const height = Math.min(items.length * ITEM_H, ITEM_H * MAX_VISIBLE);

  return (
    <div ref={ref} style={{ ...style, overflow: 'hidden', padding: '4px 0' }} {...other}>
      <div ref={scrollRef} style={{ height, overflowY: 'auto' }}>
        <div style={{ height: virtualizer.getTotalSize(), position: 'relative' }}>
          {virtualizer.getVirtualItems().map((vi) => (
            <div
              key={vi.index}
              style={{ left: 0, position: 'absolute', right: 0, top: 0, transform: `translateY(${vi.start}px)` }}
            >
              {items[vi.index]}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
});

const SupplierSearch = () => {
  const { t } = useTranslation(['purchase']);
  const dispatch = useAppDispatch();
  const supplierMobile = useSelector(selectSupplierNameOrMobile);
  const receiptNo = useSelector(selectReceiptNo);
  const basketItemCount = useAppSelector((state) => state.purchaseBasket.items.length);
  const [supplierInput, setSupplierInput] = useState('');
  const [supplierQuery, setSupplierQuery] = useState('');
  const [confirmedSupplier, setConfirmedSupplier] = useState('');
  const [receiptInput, setReceiptInput] = useState('');
  const [supplierOptions, setSupplierOptions] = useState<SupplierSearchOption[]>([]);
  const [searchValue, setSearchValue] = useState('');
  const [openAddPurchase, setOpenAddPurchase] = useState(false);
  const [selectedProduct, setSelectedProduct] = useState<IProductData | null>(null);
  const hasSupplier = confirmedSupplier.trim() !== '';

  const { data: supplierData, isFetching: fetchingSupplier } = useGetSupplierByMobileQuery(
    supplierQuery,
    { skip: !supplierQuery },
  );

  const commitSupplierReceipt = (nextSupplier: string, nextReceipt: string) => {
    dispatch(
      addMobileReceiptID({
        supplierNameOrMobile: nextSupplier,
        receiptNo: nextReceipt,
      })
    );
  };

  useEffect(() => {
    const suppliers =
      ((supplierData?.data as { suppliers: SupplierSearchOption[] })?.suppliers ??
        []);
    setSupplierOptions(suppliers);

    if (!supplierQuery.trim()) {
      return;
    }

    const normalizedQuery = normalizeSupplierValue(supplierQuery);
    const matchedSupplier = suppliers.find(
      (supplier) =>
        normalizeSupplierValue(supplier.mobile) === normalizedQuery ||
        normalizeSupplierValue(supplier.supplierName) === normalizedQuery ||
        normalizeSupplierValue(supplier.name) === normalizedQuery
    );

    setConfirmedSupplier(matchedSupplier ? getSupplierOptionMobile(matchedSupplier) : '');
  }, [supplierData, supplierInput, supplierQuery]);

  useEffect(() => {
    if (supplierMobile) {
      setSupplierInput(supplierMobile);
      setConfirmedSupplier(supplierMobile);
      return;
    }

    if (!supplierMobile && !receiptNo && basketItemCount === 0) {
      setSupplierInput('');
      setSupplierQuery('');
      setConfirmedSupplier('');
      setSupplierOptions([]);
    }
  }, [basketItemCount, receiptNo, supplierMobile]);

  useEffect(() => {
    if (!supplierQuery) {
      setSupplierOptions([]);
    }
  }, [supplierQuery]);

  useEffect(() => {
    setReceiptInput(receiptNo ?? '');
  }, [receiptNo]);

  const { productRecords, currencyCode } = usePurchase();

  const filteredProducts = useMemo(() => {
    if (!searchValue) return productRecords;
    const q = searchValue.toLowerCase().trim();
    return productRecords.filter(
      (p) => p.name?.toLowerCase().includes(q) || p.code?.toLowerCase().includes(q),
    );
  }, [productRecords, searchValue]);

  const handleProductChange = (
    _event: React.SyntheticEvent,
    newValue: string | IProductData | null,
  ) => {
    if (newValue && typeof newValue === 'object' && 'id' in newValue) {
      const product = newValue as IProductData;
      setSelectedProduct(product);
      setOpenAddPurchase(true);
      setSearchValue('');
    }
  };

  const handleReceiptChange = (
    event: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>
  ) => {
    const { value } = event.target;
    setReceiptInput(value);
    commitSupplierReceipt(confirmedSupplier, value);
  };

  const handleSupplierInputChange = (value: string) => {
    setSupplierInput(value);
    setSupplierQuery('');
    setSupplierOptions([]);
    if (value.trim() !== confirmedSupplier.trim()) {
      setConfirmedSupplier('');
      setReceiptInput('');
      commitSupplierReceipt('', '');
    }
  };

  const handleSupplierEnter = (
    event: React.KeyboardEvent<HTMLDivElement>
  ) => {
    if (event.key !== 'Enter') return;
    event.preventDefault();
    const nextSupplier = (event.target as HTMLInputElement).value.trim();
    setSupplierInput(nextSupplier);
    setSupplierQuery(nextSupplier);
  };

  return (
    <Box>
      <Grid container spacing={1} sx={{ fontWeight: 800, pb: 1 }}>
        {/* Supplier search */}
        <Grid item md={6}>
          <Autocomplete
            freeSolo
            filterOptions={(options) => options}
            getOptionLabel={(option) =>
              typeof option === 'string' ? option : getSupplierOptionMobile(option)
            }
            loading={fetchingSupplier}
            noOptionsText="No supplier found"
            onChange={(_e, val) => {
              if (typeof val === 'string' && val.trim()) {
                const nextSupplier = val.trim();
                setSupplierInput(nextSupplier);
                setSupplierQuery(nextSupplier);
              } else if (val && typeof val !== 'string') {
                const nextSupplier = getSupplierOptionMobile(val);
                setSupplierInput(nextSupplier);
                setSupplierQuery(nextSupplier);
                setConfirmedSupplier(nextSupplier);
              }
            }}
            onInputChange={(_e, val) => {
              handleSupplierInputChange(val);
            }}
            options={supplierOptions}
            renderOption={(props, option) => (
              <li {...props} key={option.id ?? getSupplierOptionMobile(option)}>
                <Box sx={{ display: 'flex', flexDirection: 'column', py: 0.25 }}>
                  <Typography sx={{ color: NAVY, fontSize: 12, fontWeight: 700, lineHeight: 1.25 }}>
                    {getSupplierOptionLabel(option)}
                  </Typography>
                  <Typography sx={{ color: alpha(NAVY, 0.6), fontSize: 11, lineHeight: 1.2 }}>
                    {getSupplierOptionMobile(option)}
                  </Typography>
                </Box>
              </li>
            )}
            value={supplierInput || ''}
            renderInput={(params) => (
              <TextField
                {...params}
                InputProps={{
                  ...params.InputProps,
                  startAdornment: (
                    <InputAdornment position="start">
                      <LocalShippingOutlinedIcon sx={{ color: TEAL, fontSize: 17 }} />
                    </InputAdornment>
                  ),
                }}
                autoComplete="off"
                fullWidth
                id="purchase-supplier-search"
                onChange={(e) => handleSupplierInputChange(e.target.value)}
                onKeyDown={handleSupplierEnter}
                placeholder="Supplier mobile…"
                size="small"
                sx={{
                  '& .MuiOutlinedInput-input': { fontSize: 13 },
                  '& .MuiOutlinedInput-root': {
                    backgroundColor: '#fff',
                    borderRadius: '10px',
                    '& fieldset': { borderColor: alpha(NAVY, 0.18) },
                    '&.Mui-focused fieldset': { borderColor: TEAL, borderWidth: '1.5px' },
                    '&:hover fieldset': { borderColor: alpha(TEAL, 0.5) },
                  },
                }}
              />
            )}
            sx={{ width: '100%' }}
          />
        </Grid>

        {/* Product search */}
        <Grid item md={6}>
          <Autocomplete
            ListboxComponent={VirtualListbox as React.ComponentType<React.HTMLAttributes<HTMLElement>>}
            freeSolo
            getOptionLabel={(option) => typeof option === 'string' ? option : option.name || ''}
            id="purchase-product-search"
            inputValue={searchValue}
            isOptionEqualToValue={(option, value) => {
              if (typeof option === 'string' || typeof value === 'string') return false;
              return option.id === value.id;
            }}
            onChange={handleProductChange}
            onInputChange={(_e, v) => setSearchValue(v)}
            options={filteredProducts}
            renderInput={(params) => (
              <TextField
                {...params}
                InputProps={{
                  ...params.InputProps,
                  startAdornment: (
                    <InputAdornment position="start">
                      <SearchIcon sx={{ color: TEAL, fontSize: 17 }} />
                    </InputAdornment>
                  ),
                  type: 'search',
                }}
                fullWidth
                placeholder="Search name or code…"
                size="small"
                sx={{
                  '& .MuiOutlinedInput-input': { fontSize: 13 },
                  '& .MuiOutlinedInput-root': {
                    backgroundColor: '#fff',
                    borderRadius: '10px',
                    '& fieldset': { borderColor: alpha(NAVY, 0.18) },
                    '&.Mui-focused fieldset': { borderColor: TEAL, borderWidth: '1.5px' },
                    '&:hover fieldset': { borderColor: alpha(TEAL, 0.5) },
                  },
                }}
              />
            )}
            renderOption={(props, option) => {
              if (typeof option === 'string') return <li {...props}>{option}</li>;
              return (
                <li {...props} key={option.id} style={{ borderRadius: '8px', cursor: 'pointer', padding: '6px 10px' }}>
                  <Box sx={{ alignItems: 'center', display: 'flex', gap: 1, width: '100%' }}>
                    <Box sx={{ background: TEAL, borderRadius: '2px', flexShrink: 0, height: 26, width: 3 }} />
                    <Box sx={{ flex: 1, minWidth: 0 }}>
                      <Typography sx={{ color: NAVY, fontSize: 12, fontWeight: 700, lineHeight: 1.3, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                        {option.name}
                      </Typography>
                      {option.code && (
                        <Typography sx={{ color: alpha(NAVY, 0.42), fontSize: 10, lineHeight: 1.2 }}>
                          {option.code}
                        </Typography>
                      )}
                    </Box>
                    {option.unitPrice !== undefined && (
                      <Typography sx={{ color: TEAL, flexShrink: 0, fontSize: 11, fontVariantNumeric: 'tabular-nums', fontWeight: 800 }}>
                        {currencyCode} {getPriceFormatWithoutCurrency(option.unitPrice)}
                      </Typography>
                    )}
                  </Box>
                </li>
              );
            }}
            slotProps={{
              paper: {
                sx: {
                  border: `1px solid ${alpha(TEAL, 0.15)}`,
                  borderRadius: '12px',
                  boxShadow: `0 8px 32px ${alpha(NAVY, 0.16)}`,
                  mt: 0.5,
                  '& .MuiAutocomplete-option': {
                    '&:hover, &.Mui-focused': { background: alpha(TEAL, 0.08) },
                    '&[aria-selected="true"]': { background: alpha(TEAL, 0.12) },
                  },
                },
              },
            }}
            sx={{ width: '100%' }}
            value={null}
          />
        </Grid>

        <Grid item xs={12}>
          <Box
            sx={{
              alignItems: { xs: 'stretch', md: 'center' },
              background: alpha(TEAL, 0.04),
              border: `1px solid ${alpha(TEAL, 0.14)}`,
              borderRadius: '10px',
              display: 'flex',
              flexDirection: { xs: 'column', md: 'row' },
              gap: 1,
              px: 1,
              py: 0.75,
            }}
          >
            <Box
              sx={{
                alignItems: 'center',
                display: 'flex',
                gap: 1,
                minWidth: 0,
              }}
            >
              <Box
                sx={{
                  alignItems: 'center',
                  background: alpha(TEAL, 0.1),
                  borderRadius: '8px',
                  color: TEAL,
                  display: 'flex',
                  flexShrink: 0,
                  height: 28,
                  justifyContent: 'center',
                  width: 28,
                }}
              >
                <ReceiptLongOutlinedIcon sx={{ fontSize: 16 }} />
              </Box>
              <Box sx={{ minWidth: 0 }}>
                <Typography
                  sx={{
                    color: alpha(NAVY, 0.5),
                    fontSize: 10,
                    fontWeight: 700,
                    letterSpacing: '0.05em',
                    textTransform: 'uppercase',
                  }}
                >
                  {hasSupplier ? `Supplier: ${confirmedSupplier}` : 'Supplier'}
                </Typography>
                <Typography
                  sx={{
                    color: NAVY,
                    fontSize: 12,
                    fontWeight: 700,
                    lineHeight: 1.2,
                  }}
                >
                  {t('purchase:receiptNumber')}
                </Typography>
              </Box>
            </Box>

            <TextField
              autoComplete="off"
              disabled={!hasSupplier}
              fullWidth
              id="purchase-receipt-number"
              onChange={handleReceiptChange}
              placeholder={t('purchase:receiptNumber')}
              size="small"
              value={receiptInput}
              sx={{
                ml: { md: 'auto' },
                maxWidth: { md: 240 },
                '& .MuiOutlinedInput-input': { fontSize: 13 },
                '& .MuiOutlinedInput-root': {
                  backgroundColor: '#fff',
                  borderRadius: '10px',
                  '& fieldset': { borderColor: alpha(NAVY, 0.18) },
                  '&.Mui-focused fieldset': { borderColor: TEAL, borderWidth: '1.5px' },
                  '&:hover fieldset': { borderColor: alpha(TEAL, 0.5) },
                },
              }}
            />
          </Box>
        </Grid>
      </Grid>

      {openAddPurchase && selectedProduct && (
        <AddPurchase
          data={selectedProduct}
          handleCloseDialog={() => {
            setOpenAddPurchase(false);
            setSelectedProduct(null);
          }}
          openModel={openAddPurchase}
          title="Add Purchase Item"
        />
      )}
    </Box>
  );
};

export default React.memo(SupplierSearch);
